# Devin MCP

Use the authenticated Devin MCP for Devin's private-repository documentation and live platform state. The server can also manage Sessions, playbooks, Knowledge, schedules, and integrations.

Official reference: [Devin MCP](https://docs.devin.ai/work-with-devin/devin-mcp).

Create an organization-scoped service-user key in Devin under **Settings → Service users**. The key must start with `cog_`; legacy `apk_` keys do not work.

Export the key before starting a coding agent:

```bash
export DEVIN_API_KEY="cog_..."
```

Keep the value outside Git. The checked-in configurations read only the environment variable:

- Codex: `.codex/config.toml`
- Claude Code: `.mcp.json`
- Cursor: `.cursor/mcp.json`
- Gemini CLI: `.gemini/settings.json`

Restart the client after setting the key. Verify with `codex mcp list`, `claude mcp list`, `agent mcp list`, or Gemini's `/mcp list`.

## Source precedence

1. Use the checked-out code and configuration for current implementation truth.
2. Use specifications, ADRs, and design documents for intent and accepted decisions.
3. Use Devin Wiki as a map for unfamiliar or cross-repository code, then verify its claims against sources.

Generated Wiki content is an index, not durable truth. Confirm the repository and branch before relying on it.

## Use when

- The task spans repositories or asks about code missing from the current checkout.
- Broad architecture discovery would benefit from Wiki structure, citations, or cross-repository questions.
- The task asks for history or status from a Devin Session.
- The developer asks to create or manage Sessions, playbooks, Knowledge, schedules, or integrations.

Use local search first for ordinary work inside this checkout.

## Authorization

Repository and Wiki reads are normal research. Cross-check conclusions before changing code.

Creating Sessions can spend ACUs. Sending messages, terminating Sessions, and changing playbooks, Knowledge, schedules, or integrations mutate shared external state. Perform those actions only when the developer explicitly requests them.

Never print, log, or commit `DEVIN_API_KEY`.
import { useCallback, useEffect, useState } from "react"

import {
  getStepResponse,
  SCRIPT,
  STEP_SETTLE_DELAY_MS,
  STREAM_CHARS_PER_TICK,
  STREAM_TICK_MS,
} from "@/lib/case-001"

type PlaybackPhase = "waiting" | "text"
type PlaybackStatus = "streaming" | "stopped" | "complete"
type RehearsalTurnPhase = "pending" | "streaming" | "stopped" | "complete"

type PlaybackState = {
  status: PlaybackStatus
  phase: PlaybackPhase
  stepIndex: number
  text: string
}

const INITIAL_STATE: PlaybackState = {
  status: "streaming",
  phase: "waiting",
  stepIndex: 0,
  text: "",
}

// This hook is the timer-driven replacement seam for a live Devin Session.
// Keep its contract small so the Cockpit can later consume server events instead.
export function useDeterministicRehearsal() {
  const [playback, setPlayback] = useState<PlaybackState>(INITIAL_STATE)

  useEffect(() => {
    if (playback.status !== "streaming") return

    const step = SCRIPT[playback.stepIndex]
    if (!step) return

    if (playback.phase === "waiting") {
      const timeout = window.setTimeout(() => {
        setPlayback((current) => {
          if (
            current.status !== "streaming" ||
            current.phase !== "waiting" ||
            current.stepIndex !== playback.stepIndex
          ) {
            return current
          }

          return { ...current, phase: "text", text: "" }
        })
      }, step.waitMs)

      return () => window.clearTimeout(timeout)
    }

    const response = getStepResponse(step)
    if (playback.text.length < response.length) {
      const timeout = window.setTimeout(() => {
        setPlayback((current) => {
          if (
            current.status !== "streaming" ||
            current.phase !== "text" ||
            current.stepIndex !== playback.stepIndex
          ) {
            return current
          }

          const nextLength = Math.min(
            current.text.length + STREAM_CHARS_PER_TICK,
            response.length
          )
          return { ...current, text: response.slice(0, nextLength) }
        })
      }, STREAM_TICK_MS)

      return () => window.clearTimeout(timeout)
    }

    const timeout = window.setTimeout(() => {
      setPlayback((current) => {
        if (
          current.status !== "streaming" ||
          current.phase !== "text" ||
          current.stepIndex !== playback.stepIndex
        ) {
          return current
        }

        const nextStepIndex = current.stepIndex + 1
        if (nextStepIndex === SCRIPT.length) {
          return {
            status: "complete",
            phase: "waiting",
            stepIndex: nextStepIndex,
            text: "",
          }
        }

        return {
          status: "streaming",
          phase: "waiting",
          stepIndex: nextStepIndex,
          text: "",
        }
      })
    }, STEP_SETTLE_DELAY_MS)

    return () => window.clearTimeout(timeout)
  }, [playback])

  const stop = useCallback(() => {
    setPlayback((current) => {
      if (current.status !== "streaming") return current
      return { ...current, status: "stopped" }
    })
  }, [])

  const replay = useCallback(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setPlayback({
        status: "complete",
        phase: "waiting",
        stepIndex: SCRIPT.length,
        text: "",
      })
      return
    }

    setPlayback(INITIAL_STATE)
  }, [])

  const currentStepIndex =
    playback.status === "streaming" ||
    (playback.status === "stopped" && playback.phase === "text")
      ? playback.stepIndex
      : null
  const currentPhase: RehearsalTurnPhase | null =
    currentStepIndex === null
      ? null
      : playback.status === "stopped"
        ? "stopped"
        : playback.phase === "waiting"
          ? "pending"
          : playback.text === getStepResponse(SCRIPT[playback.stepIndex])
            ? "complete"
            : "streaming"
  const revealedSteps =
    playback.status === "complete"
      ? SCRIPT.length
      : playback.stepIndex + (playback.phase === "text" ? 1 : 0)

  return {
    completedSteps: playback.stepIndex,
    currentPhase,
    currentStepIndex,
    currentText: playback.text,
    revealedSteps,
    running: playback.status === "streaming",
    replay,
    stop,
  }
}
"use client"

import { Suspense, useEffect, useState } from "react"
import {
  Conversation,
  ConversationContent,
  ConversationScrollButton,
} from "@/components/ai-elements/conversation"
import {
  Message,
  MessageContent,
  MessageResponse,
} from "@/components/ai-elements/message"
import {
  AssistantTurn,
  CompletedRunSummary,
} from "@/components/cockpit/assistant-turn"
import { CallDetailDialog } from "@/components/cockpit/call-detail-dialog"
import { CandidatePanel } from "@/components/cockpit/candidate-panel"
import { CockpitShell } from "@/components/cockpit/cockpit-shell"
import {
  DecisionBar,
  type DecisionStatus,
} from "@/components/cockpit/decision-bar"
import { DotLoader } from "@/components/cockpit/dot-loader"
import { IncidentHeader } from "@/components/cockpit/incident-header"
import { IncidentRequestMessage } from "@/components/cockpit/incident-request-message"
import { MessageComposer } from "@/components/cockpit/message-composer"
import { useDeterministicRehearsal } from "@/hooks/use-deterministic-rehearsal"
import { FINAL_MESSAGE, SCRIPT, SEND_DELAY_MS } from "@/lib/case-001"

export function CockpitChat() {
  const rehearsal = useDeterministicRehearsal()
  const [approved, setApproved] = useState(false)
  const [candidatesOpen, setCandidatesOpen] = useState(true)
  const [draft, setDraft] = useState("")
  const [messages, setMessages] = useState<string[]>([])
  const [pendingMessage, setPendingMessage] = useState<string | null>(null)
  const running = rehearsal.running
  const visible = rehearsal.revealedSteps

  useEffect(() => {
    if (pendingMessage === null) return

    const timeout = window.setTimeout(() => {
      setMessages((current) => [...current, pendingMessage])
      setPendingMessage(null)
    }, SEND_DELAY_MS)

    return () => window.clearTimeout(timeout)
  }, [pendingMessage])

  const currentStep =
    rehearsal.currentStepIndex === null
      ? null
      : SCRIPT[rehearsal.currentStepIndex]
  const checksPassed = isStepVisible("tests", visible)
  const decisionExists = isStepVisible("strategy", visible)
  const decisionStatus: DecisionStatus = approved
    ? "approved"
    : !running && !checksPassed
      ? "on hold"
      : checksPassed
        ? "needs human review"
        : "evaluating"

  function replay() {
    rehearsal.replay()
    setApproved(false)
  }

  function sendMessage(message: string) {
    const text = message.trim()
    if (!text || running || pendingMessage !== null) return

    setDraft("")
    setPendingMessage(text)
  }

  const composerStatus = running
    ? "streaming"
    : pendingMessage !== null
      ? "submitted"
      : "ready"
  const conversationStepCount =
    rehearsal.completedSteps + (rehearsal.currentStepIndex === null ? 0 : 1)
  const complete =
    visible === SCRIPT.length && rehearsal.currentStepIndex === null

  return (
    <CockpitShell
      rightSidebar={
        candidatesOpen ? (
          <CandidatePanel
            visible={visible}
            onClose={() => setCandidatesOpen(false)}
          />
        ) : undefined
      }
    >
      <div className="grid h-full min-h-0 min-w-0 grid-rows-[auto_minmax(0,1fr)_auto] overflow-hidden">
        <IncidentHeader
          visible={visible}
          approved={approved}
          running={running}
          onReplay={replay}
          showOpenCandidates={!candidatesOpen}
          onOpenCandidates={() => setCandidatesOpen(true)}
        />
        <Conversation className="min-h-0">
          <ConversationContent
            className="mx-auto w-full max-w-[50vw] gap-4 px-4 py-4"
            scrollClassName="chat-scrollbar overflow-x-hidden overflow-y-auto"
          >
            <IncidentRequestMessage />
            {complete ? (
              <>
                <CompletedRunSummary steps={SCRIPT} />
                <Message from="assistant" className="max-w-full">
                  <MessageContent>
                    <MessageResponse>{FINAL_MESSAGE}</MessageResponse>
                  </MessageContent>
                </Message>
              </>
            ) : (
              SCRIPT.slice(0, conversationStepCount).map((step, index) => {
                const current = index === rehearsal.currentStepIndex

                return (
                  <AssistantTurn
                    key={step.id}
                    step={step}
                    phase={
                      current && rehearsal.currentPhase
                        ? rehearsal.currentPhase
                        : "complete"
                    }
                    text={current ? rehearsal.currentText : undefined}
                  />
                )
              })
            )}
            {running ? (
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <DotLoader className="size-4" />
                <span>{currentStep?.stepName ?? "Launching"}</span>
              </div>
            ) : null}
            {messages.map((message, index) => (
              <Message key={`${index}-${message}`} from="user">
                <MessageContent>
                  <p>{message}</p>
                </MessageContent>
              </Message>
            ))}
          </ConversationContent>
          <ConversationScrollButton />
        </Conversation>
        <div className="shrink-0 bg-background">
          {decisionExists ? (
            <DecisionBar
              checksPassed={checksPassed}
              status={decisionStatus}
              onApprove={() => setApproved(true)}
            />
          ) : null}
          <MessageComposer
            value={draft}
            status={composerStatus}
            onChange={setDraft}
            onSend={sendMessage}
            onStop={rehearsal.stop}
          />
        </div>
      </div>
      <Suspense fallback={null}>
        <CallDetailDialog />
      </Suspense>
    </CockpitShell>
  )
}

function isStepVisible(stepId: string, visible: number): boolean {
  const index = SCRIPT.findIndex((step) => step.id === stepId)
  return index >= 0 && visible > index
}
